{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-02",
  "sketch": {
    "components": ["Storefront client", "Public GraphQL endpoint", "GraphQL resolvers", "Product service", "Review service", "Customer profile service"],
    "dataStores": ["Product catalogue", "Reviews store", "Customer profile store"],
    "externalServices": [],
    "trustBoundaries": ["Internet to public GraphQL endpoint", "GraphQL resolvers to customer profile store"],
    "dataClasses": ["pii"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Anyone on the internet can query customer profiles through the public endpoint",
      "scenario": "The endpoint is public and the design names customer profiles as a queryable type, with no authentication or per-object authorization described. An attacker sends a crafted query for customer profiles (or iterates customer ids) directly from the internet and harvests personal data for the whole customer base in bulk.",
      "component": "Public GraphQL endpoint / customer profile resolver",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The storefront uses a public GraphQL endpoint. Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": ["V8.1.1"],
      "cwe": ["CWE-306", "CWE-639"],
      "plainLanguage": "Anyone could ask the storefront API for other shoppers' personal details, because nothing checks who is asking.",
      "requirement": {
        "title": "Authenticate and authorize every customer profile field",
        "given": "an unauthenticated or unrelated caller on the public GraphQL endpoint",
        "when": "the query requests any customer profile type or field",
        "then": "the resolver denies the request unless the authenticated subject owns that profile, and returns no profile data"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Nested traversal from public products and reviews reaches private profile fields",
      "scenario": "Even if the top-level profile query is protected, the schema lets a client walk product -> reviews -> author -> customer profile. An attacker starts from a public product query and pivots through nested edges to read email, address or order history of reviewers, bypassing the checks that exist only on the entry point.",
      "component": "GraphQL resolvers (nested edges)",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": ["V8.1.1"],
      "cwe": ["CWE-863"],
      "plainLanguage": "A shopper could start from a public product page query and follow links in the data all the way to private customer details.",
      "requirement": {
        "title": "Enforce authorization on every resolver, not just root queries",
        "given": "a query that reaches a sensitive type through a nested edge such as product -> review -> author",
        "when": "the nested resolver executes",
        "then": "the same object and field level authorization is applied as on the root query, and unauthorized fields resolve to null with an authorization error"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Deeply nested or recursive query exhausts the API with one request",
      "scenario": "The design advertises nested queries with no depth, complexity or cost limits. An unauthenticated attacker posts a query that cycles product -> reviews -> author -> reviews repeatedly, multiplying resolver and database calls thousands of times. A handful of such requests saturate the storefront API and take the shop offline.",
      "component": "Public GraphQL endpoint query execution",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": [],
      "cwe": ["CWE-770", "CWE-674"],
      "plainLanguage": "One cleverly written query could ask for so much nested data that it knocks the storefront API over.",
      "requirement": {
        "title": "Limit query depth and cost",
        "given": "an unauthenticated request to the public GraphQL endpoint",
        "when": "the query exceeds the configured maximum depth, node count or computed complexity cost",
        "then": "the request is rejected before execution with an error and no resolvers run"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Production introspection hands attackers the full schema",
      "scenario": "Introspection is on in production, so any anonymous caller downloads the complete schema including internal, deprecated and admin-only fields, argument names and mutations. This removes all guesswork and lets the attacker aim directly at the weakest resolver or an unintentionally exposed field.",
      "component": "Public GraphQL endpoint introspection",
      "likelihood": 5,
      "impact": 3,
      "evidence": [
        { "quote": "Introspection is enabled in production." }
      ],
      "asvs": [],
      "cwe": ["CWE-200"],
      "plainLanguage": "The API publishes a full map of itself, including fields that were never meant for customers, so attackers know exactly what to try.",
      "requirement": {
        "title": "Disable introspection for untrusted callers in production",
        "given": "the production deployment of the storefront GraphQL endpoint",
        "when": "an unauthenticated client sends an __schema or __type introspection query",
        "then": "the request is rejected and no schema metadata is returned"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Query batching and field aliases multiply work and defeat per-request limits",
      "scenario": "A public GraphQL endpoint typically accepts arrays of operations and repeated aliased fields. An attacker packs hundreds of profile or review lookups into one HTTP request, so any per-request rate limit or throttle counts it once. This both amplifies load and lets them enumerate customer records or brute force lookup arguments quickly.",
      "component": "Public GraphQL endpoint request handling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The storefront uses a public GraphQL endpoint." }
      ],
      "asvs": [],
      "cwe": ["CWE-799"],
      "plainLanguage": "Attackers can hide hundreds of lookups inside a single request, so limits that count requests do not slow them down.",
      "requirement": {
        "title": "Bound batched operations and aliased fields",
        "given": "a request containing multiple operations or repeated aliases of the same field",
        "when": "the number of operations or aliased sensitive fields exceeds the configured limit",
        "then": "the request is rejected, and quota is consumed per operation rather than per HTTP request"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Verbose GraphQL errors and field suggestions leak internals",
      "scenario": "Default GraphQL servers return did-you-mean field suggestions, resolver stack traces and database messages. On a public endpoint an attacker probes invalid fields and arguments and reconstructs hidden parts of the schema and backend technology even if introspection is later turned off, guiding the attacks above.",
      "component": "GraphQL error handling",
      "likelihood": 3,
      "impact": 2,
      "evidence": [
        { "quote": "Introspection is enabled in production." }
      ],
      "asvs": [],
      "cwe": ["CWE-209"],
      "plainLanguage": "Error messages that suggest the correct field name or show stack traces let outsiders map the API by guessing.",
      "requirement": {
        "title": "Return sanitized errors to public callers",
        "given": "a malformed or unauthorized query on the production endpoint",
        "when": "the server builds the error response",
        "then": "it returns a generic message without stack traces, backend details or field name suggestions, and logs the detail server side"
      }
    }
  ]
}

{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-02",
  "sketch": {
    "components": ["Storefront client", "Public GraphQL endpoint", "GraphQL resolvers", "Product service", "Review service", "Customer profile service"],
    "dataStores": ["Product catalogue", "Reviews store", "Customer profile store"],
    "externalServices": [],
    "trustBoundaries": ["Internet to public GraphQL endpoint", "GraphQL resolvers to customer profile data"],
    "dataClasses": ["pii"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Anyone on the internet can read customer profiles through nested queries",
      "scenario": "The endpoint is public and the design places customer profiles in the same graph as products and reviews. An unauthenticated attacker queries products -> reviews -> author -> customer profile and walks the graph to harvest names, emails and addresses of many customers in bulk, without ever touching a profile endpoint directly.",
      "component": "Public GraphQL endpoint / customer profile resolvers",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        { "quote": "The storefront uses a public GraphQL endpoint. Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-200", "CWE-285"],
      "plainLanguage": "A stranger could ask the storefront API for customer names and emails by following links from products to reviews to profiles.",
      "requirement": {
        "title": "Authorize every customer profile field in the graph",
        "given": "an unauthenticated or non-owner client calling the public GraphQL endpoint",
        "when": "it requests customer profile fields directly or by traversing product and review relationships",
        "then": "the resolver denies the field and returns no personal data unless the caller is the profile owner or an authorized staff role"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "No authentication required on an endpoint that serves personal data",
      "scenario": "Deterministic signals show auth is false while exposure is public. An attacker needs no account, token or session to call the endpoint, so every resolver that returns non-public data is reachable anonymously and there is no identity to tie a request to for rate limiting or revocation.",
      "component": "Public GraphQL endpoint",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        { "quote": "\"exposure\":\"public\",\"llmFeatures\":false,\"fileUpload\":false,\"auth\":false" },
        { "quote": "The storefront uses a public GraphQL endpoint." }
      ],
      "asvs": [],
      "cwe": ["CWE-306"],
      "plainLanguage": "The API does not ask who you are, so anything beyond public catalogue data is open to everyone.",
      "requirement": {
        "title": "Split anonymous and authenticated parts of the schema",
        "given": "the public GraphQL endpoint",
        "when": "a request asks for any field other than the public catalogue",
        "then": "the request is rejected unless it carries a valid authenticated session or token for the storefront"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Deeply nested or recursive queries exhaust the API",
      "scenario": "Because clients choose the shape of the query, an attacker sends a deeply nested cycle such as product -> reviews -> author -> reviews -> product repeated dozens of levels. One small HTTP request fans out into millions of resolver calls and database reads, making the storefront unavailable for real shoppers at near-zero cost to the attacker.",
      "component": "GraphQL resolvers / query execution",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": [],
      "cwe": ["CWE-770", "CWE-674"],
      "plainLanguage": "One tiny request that asks for data inside data inside data can overload the server and take the shop offline.",
      "requirement": {
        "title": "Enforce query depth and cost limits",
        "given": "any query sent to the public GraphQL endpoint",
        "when": "its nesting depth or computed complexity cost exceeds the configured limit",
        "then": "the server rejects the query before execution with an error and does not resolve any field"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Introspection in production hands attackers the full schema",
      "scenario": "With introspection enabled in production, an anonymous attacker runs the __schema query and receives every type, field, argument and mutation, including internal or not-yet-released fields that the storefront UI never calls. This removes all guesswork and lets them go straight to the profile and admin-ish fields most likely to be unprotected.",
      "component": "Public GraphQL endpoint (introspection)",
      "likelihood": 5,
      "impact": 3,
      "evidence": [
        { "quote": "Introspection is enabled in production." }
      ],
      "asvs": [],
      "cwe": ["CWE-200"],
      "plainLanguage": "The API publishes a complete map of itself, so attackers can see every hidden field instead of guessing.",
      "requirement": {
        "title": "Disable introspection in production",
        "given": "the production deployment of the storefront GraphQL endpoint",
        "when": "a client sends an introspection query such as __schema or __type",
        "then": "the server refuses the query, and schema documentation is only available in non-production or to authorized internal users"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Guessing or enumerating another customer's profile id",
      "scenario": "Profiles are exposed as a queryable type, so an attacker calls customer(id: ...) and iterates or guesses identifiers. Without an ownership check in the resolver, each call returns a different person's profile, letting one authenticated shopper enumerate the whole customer base.",
      "component": "Customer profile resolver",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-639"],
      "plainLanguage": "Changing the customer id in a request could show you somebody else's account details.",
      "requirement": {
        "title": "Ownership check on profile lookups",
        "given": "a logged-in storefront customer",
        "when": "they query a customer profile whose id is not their own",
        "then": "the server returns an authorization error and no profile fields, and the attempt is recorded"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Aliased and batched queries defeat per-request limits",
      "scenario": "An attacker puts hundreds of aliased copies of an expensive field, or an array of batched operations, inside a single HTTP POST. Controls that count HTTP requests see one request while the server performs hundreds of expensive lookups, which also enables fast brute-force enumeration of profiles or review authors behind a single request.",
      "component": "GraphQL endpoint request handling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The storefront uses a public GraphQL endpoint. Clients can request nested queries of products, reviews and customer profiles." }
      ],
      "asvs": [],
      "cwe": ["CWE-770"],
      "plainLanguage": "A single request can secretly contain hundreds of lookups, so limits that count requests do not actually limit anything.",
      "requirement": {
        "title": "Limit aliases and batched operations",
        "given": "a single HTTP request to the GraphQL endpoint",
        "when": "it contains more than the allowed number of operations or repeated aliases of the same expensive field",
        "then": "the server rejects the request and limits are applied per resolved field rather than per HTTP request"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Field suggestions and verbose errors leak the hidden schema",
      "scenario": "Even if introspection is later turned off, default GraphQL error handling replies 'Cannot query field x, did you mean customerEmail?' and returns resolver stack traces. An anonymous attacker reconstructs the schema and learns internal type and service names from error text alone.",
      "component": "GraphQL error handling",
      "likelihood": 3,
      "impact": 2,
      "evidence": [
        { "quote": "Introspection is enabled in production." }
      ],
      "asvs": [],
      "cwe": ["CWE-209"],
      "plainLanguage": "Error messages that say 'did you mean...' tell an attacker the real field names.",
      "requirement": {
        "title": "Suppress schema hints in production errors",
        "given": "the production GraphQL endpoint",
        "when": "a query references an unknown field or a resolver throws",
        "then": "the client receives a generic error with no field suggestions, type names or stack traces, and details go only to server-side logs"
      }
    }
  ]
}
